def show(label, obj, kind, owner, name, params)
  want = "#<#{kind}: #{owner}##{name}(#{params.join(', ')})>"
  got = obj.inspect.sub(/ \S+:\d+>/, ">")
  puts "#{label} #{got.size} #{got == want}"
end

